#include "resident/checkpoint/checkpoint_decode_lifecycle.hpp"
#include "resident/domains/politics/politics_projection_detail.hpp"
// JSON与二进制共用精确四表/原实际结果字段，不从旧Politics事实猜新权源。
#include "political_subordinate_appointment_codec.hpp"
#include "resident/domains/local_economy/local_economy_codec_detail.hpp"
#include "resident/domains/politics/takeover/politics_takeover_payload_guard.hpp"
namespace hanmo::resident::dynamic_economy_codec {
template<class A>void record(A& a,PoliticalSuccessionPlayerReceipt& v){a("actor_id",v.actor_id);a("result_id",v.result_id);a("request_sequence",v.request_sequence);a("result_revision",v.result_revision);}
template<class A>void record(A& a,PoliticalSubordinateAppointmentOffer& v){a("id",v.id);a("policy_id",v.policy_id);a("organization_id",v.organization_id);a("office_id",v.office_id);a("head_office_id",v.head_office_id);a("issuer_actor_id",v.issuer_actor_id);a("candidate_actor_id",v.candidate_actor_id);a("grant_id",v.grant_id);a("head_epoch",v.head_epoch);a("target_epoch",v.target_epoch);a("jurisdiction_revision",v.jurisdiction_revision);a("tick",v.tick);a("response_until",v.response_until);a("player_receipt",v.player_receipt);}
template<class A>void record(A& a,PoliticalSubordinateAppointmentAnswer& v){a("id",v.id);a("offer_fact_id",v.offer_fact_id);a("actor_id",v.actor_id);a("tick",v.tick);a("arrival_until",v.arrival_until);a("accepted",v.accepted);a("player_receipt",v.player_receipt);}
template<class A>void record(A& a,PoliticalSubordinateAppointmentWithdrawal& v){a("id",v.id);a("offer_fact_id",v.offer_fact_id);a("actor_id",v.actor_id);a("grant_id",v.grant_id);a("head_epoch",v.head_epoch);a("tick",v.tick);a("player_receipt",v.player_receipt);}
template<class A>void record(A& a,PoliticalSubordinateAppointmentArrival& v){a("id",v.id);a("acceptance_fact_id",v.acceptance_fact_id);a("actor_id",v.actor_id);a("office_change_fact_id",v.office_change_fact_id);a("tick",v.tick);a("installed_epoch",v.installed_epoch);a("player_receipt",v.player_receipt);}
template<class A>void record(A& a,PoliticalSubordinateAppointmentAuthoredOrigin& v){a("intent_id",v.intent_id);a("director_policy_id",v.director_policy_id);a("actor_id",v.actor_id);a("offer_fact_id",v.offer_fact_id);a("stage",v.stage);}
template<class A>void record(A& a,PoliticalSubordinateAppointmentState& v){a("version",v.version);a("offers",v.offers);a("answers",v.answers);a("withdrawals",v.withdrawals);a("arrivals",v.arrivals);a("authored_origins",v.authored_origins);}
template<class A>void record(A& a,PoliticalOfferSubordinateAppointment& v){a("authority",v.authority);a("policy_id",v.policy_id);a("candidate_actor_id",v.candidate_actor_id);a("expected_target_epoch",v.expected_target_epoch);a("expected_jurisdiction_revision",v.expected_jurisdiction_revision);}
template<class A>void record(A& a,PoliticalAnswerSubordinateAppointment& v){a("offer_fact_id",v.offer_fact_id);a("accept",v.accept);}
template<class A>void record(A& a,PoliticalWithdrawSubordinateAppointment& v){a("authority",v.authority);a("offer_fact_id",v.offer_fact_id);}
template<class A>void record(A& a,PoliticalArriveSubordinateAppointment& v){a("acceptance_fact_id",v.acceptance_fact_id);a("expected_target_epoch",v.expected_target_epoch);}
}
namespace hanmo::resident {
Status validate_political_subordinate_appointment_layout(const PoliticalSubordinateAppointmentState& s){if(s.version!=1||s.offers.size()+s.answers.size()+s.withdrawals.size()+s.arrivals.size()>4096||s.authored_origins.size()>4096)return common_failure("InvalidPoliticalSubordinateAppointmentLayout");return common_success();}
Status emit_political_subordinate_appointment_state_fields(ProjectionWriter& writer,const PoliticalSubordinateAppointmentState& s){
 try{return dynamic_economy_codec::emit_fields(writer,s);}
 catch(const boundary::DecodeFailure& e){return writer.reject(e.error.original.code,e.error.original.path);}
}
BoundaryValue encode_political_subordinate_appointment_state(const PoliticalSubordinateAppointmentState& s){return politics_projection_detail::encode_fields(s,emit_political_subordinate_appointment_state_fields);}
Outcome<PoliticalSubordinateAppointmentState> decode_political_subordinate_appointment_state(const BoundaryValue& value){auto unique=validate_political_takeover_payload(value);if(!unique.ok)return {false,{},unique.error};try{PoliticalSubordinateAppointmentState out;dynamic_economy_codec::decode(value,out,"/political_subordinate_appointments");auto valid=validate_political_subordinate_appointment_layout(out);return valid.ok?Outcome<PoliticalSubordinateAppointmentState>{true,std::move(out),{}}:Outcome<PoliticalSubordinateAppointmentState>{false,{},valid.error};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Status visit_political_subordinate_appointment_checkpoint(CodecVisitor& v,PoliticalSubordinateAppointmentState& s){auto valid=validate_political_subordinate_appointment_layout(s);if(!v.reading()&&!valid.ok)return valid;auto status=dynamic_economy_codec::checkpoint(v,political_subordinate_appointment_module,s);return status.ok?validate_political_subordinate_appointment_layout(s):status;}
StableId political_subordinate_appointment_command_kind(const PoliticalSubordinateAppointmentCommand& c){return std::visit([](const auto& v)->StableId{using T=std::decay_t<decltype(v)>;if constexpr(std::is_same_v<T,PoliticalOfferSubordinateAppointment>)return political_subordinate_offer_command;else if constexpr(std::is_same_v<T,PoliticalAnswerSubordinateAppointment>)return political_subordinate_answer_command;else if constexpr(std::is_same_v<T,PoliticalWithdrawSubordinateAppointment>)return political_subordinate_withdraw_command;else return political_subordinate_arrive_command;},c);}
bool is_political_subordinate_appointment_command(const StableId& kind){return kind==political_subordinate_offer_command||kind==political_subordinate_answer_command||kind==political_subordinate_withdraw_command||kind==political_subordinate_arrive_command;}
BoundaryValue encode_political_subordinate_appointment_command(const PoliticalSubordinateAppointmentCommand& c){return std::visit([](const auto& v){return dynamic_economy_codec::encode(v);},c);}
Outcome<PoliticalSubordinateAppointmentCommand> decode_political_subordinate_appointment_command(const StableId& kind,const BoundaryValue& value){auto unique=validate_political_takeover_payload(value);if(!unique.ok)return {false,{},unique.error};try{PoliticalSubordinateAppointmentCommand out;if(kind==political_subordinate_offer_command){PoliticalOfferSubordinateAppointment c;dynamic_economy_codec::decode(value,c,kind);out=std::move(c);}else if(kind==political_subordinate_answer_command){PoliticalAnswerSubordinateAppointment c;dynamic_economy_codec::decode(value,c,kind);out=std::move(c);}else if(kind==political_subordinate_withdraw_command){PoliticalWithdrawSubordinateAppointment c;dynamic_economy_codec::decode(value,c,kind);out=std::move(c);}else if(kind==political_subordinate_arrive_command){PoliticalArriveSubordinateAppointment c;dynamic_economy_codec::decode(value,c,kind);out=std::move(c);}else return {false,{},common_failure("UnknownPoliticalSubordinateAppointmentCommand",kind).error};return {true,std::move(out),{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
}
